changeSet.sql:
CREATE TABLE stop_factors.stop_factor_metric ( id BIGINT NOT NULL, created_date TIMESTAMP(6), updated_date TIMESTAMP(6), title VARCHAR(255) NOT NULL, calculator VARCHAR(64) NOT NULL, params JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT true, CONSTRAINT pk_stop_factor_metric PRIMARY KEY (id), CONSTRAINT uq_stop_factor_metric_title UNIQUE (title), CONSTRAINT ck_stop_factor_metric_params_is_array CHECK (jsonb_typeof(params) = 'array'), CONSTRAINT ck_stop_factor_metric_calculator CHECK (calculator IN ( 'OVERDUE_BUCKET_COUNT', 'RESTRUCTURING_COUNT', 'BUREAU_REQUESTS_COUNT', 'NEW_CREDITS_COUNT', 'KIB_REFUSAL_STATUSES', 'KIB_ACTIVE_DISPUTES', 'KIB_UNJUSTIFIED_DISPUTES', 'CURRENT_OVERDUE_DAYS', 'CURRENT_OVERDUE_AMOUNT', 'OPEN_CREDITS_COUNT')) );
CREATE SEQUENCE public.stop_factor_metric_id_generator START WITH 1 INCREMENT BY 1;
INSERT INTO stop_factors.stop_factor_metric (id, created_date, title, calculator, params) SELECT m.id, now(), m.title, m.calculator, m.params::jsonb FROM (VALUES ( 1, 'Отказные статусы в КИБ', 'KIB_REFUSAL_STATUSES', '[]'), ( 2, 'Активные споры КИБ', 'KIB_ACTIVE_DISPUTES', '[]'), ( 3, 'Необоснованные споры КИБ', 'KIB_UNJUSTIFIED_DISPUTES', '[]'), ( 4, 'Реструктуризации', 'RESTRUCTURING_COUNT', '[{"key": "source", "label": "Источник (KIB или OB)", "required": true}, {"key": "periodFromMonth", "label": "Период с (месяц)", "required": true}, {"key": "periodToMonth", "label": "Период по (месяц)", "required": true}]'), ( 5, 'Запросы в кредитное бюро', 'BUREAU_REQUESTS_COUNT', '[{"key": "days", "label": "Последние N дней", "required": true}]'), ( 6, 'Текущие дни просрочки', 'CURRENT_OVERDUE_DAYS', '[]'), ( 7, 'Текущая сумма просрочки', 'CURRENT_OVERDUE_AMOUNT', '[]'), ( 8, 'Новые открытые кредиты', 'NEW_CREDITS_COUNT', '[{"key": "days", "label": "Последние N дней", "required": true}]'), ( 9, 'Открытые кредиты', 'OPEN_CREDITS_COUNT', '[]'), (10, 'Непрерывная просроченная задолженность', 'OVERDUE_BUCKET_COUNT', '[{"key": "periodFromMonth", "label": "Период с (месяц)", "required": true}, {"key": "periodToMonth", "label": "Период по (месяц)", "required": true}, {"key": "minOverdueDays", "label": "Максимальная просрочка от (дней)", "required": true}, {"key": "maxOverdueDays", "label": "Максимальная просрочка до (дней)", "required": false}]') ) AS m (id, title, calculator, params);
SELECT setval('public.stop_factor_metric_id_generator', (SELECT COALESCE(max(id), 0) + 1 FROM stop_factors.stop_factor_metric), false);

-- One row per group version: a change of any of its stop factors closes the version (valid_to) and -- creates the next one with copies of all of them, so a check keeps the rules it ran with CREATE TABLE stop_factors.stop_factor_group ( id BIGINT NOT NULL, created_date TIMESTAMP(6), updated_date TIMESTAMP(6), root_id BIGINT, version_number INTEGER NOT NULL DEFAULT 1, name VARCHAR(255) NOT NULL, description TEXT, order_number INTEGER NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, valid_from TIMESTAMP(6) NOT NULL, valid_to TIMESTAMP(6), change_reason VARCHAR(255), CONSTRAINT pk_stop_factor_group PRIMARY KEY (id), CONSTRAINT fk_stop_factor_group_root FOREIGN KEY (root_id) REFERENCES stop_factors.stop_factor_group (id), CONSTRAINT ck_stop_factor_group_root CHECK ((root_id IS NULL) = (version_number = 1)), CONSTRAINT ck_stop_factor_group_validity CHECK (valid_to IS NULL OR valid_to >= valid_from) );
CREATE UNIQUE INDEX ux_stop_factor_group_current_version ON stop_factors.stop_factor_group ((COALESCE(root_id, id))) WHERE valid_to IS NULL; CREATE UNIQUE INDEX ux_stop_factor_group_version_number ON stop_factors.stop_factor_group ((COALESCE(root_id, id)), version_number); CREATE UNIQUE INDEX ux_stop_factor_group_current_name ON stop_factors.stop_factor_group (name) WHERE valid_to IS NULL;
CREATE SEQUENCE public.stop_factor_group_id_generator START WITH 1 INCREMENT BY 1;
INSERT INTO stop_factors.stop_factor_group (id, created_date, name, order_number, valid_from, change_reason) SELECT g.id, now(), g.name, g.id, COALESCE((SELECT min(created_date) FROM stop_factors.stop_factor), now()), 'Стоп-факторы SPR' FROM (VALUES (1, 'Статусы и споры КИБ'), (2, 'Реструктуризации'), (3, 'Кредитная активность'), (4, 'Текущая просрочка'), (5, 'История просрочек') ) AS g (id, name);
SELECT setval('public.stop_factor_group_id_generator', (SELECT COALESCE(max(id), 0) + 1 FROM stop_factors.stop_factor_group), false);

ALTER TABLE stop_factors.stop_factor ADD COLUMN group_id BIGINT, ADD COLUMN metric_id BIGINT, ADD COLUMN segment VARCHAR(32), ADD COLUMN params JSONB NOT NULL DEFAULT '{}'::jsonb;
-- Group, metric and params of each legacy stop factor; one missing here fails SET NOT NULL below UPDATE stop_factors.stop_factor f SET group_id = m.group_id, metric_id = m.metric_id, params = m.params::jsonb FROM (VALUES ( 1, 1, 1, '{}'), ( 2, 1, 2, '{}'), ( 3, 1, 3, '{}'), ( 4, 2, 4, '{"source": "KIB", "periodFromMonth": 1, "periodToMonth": 12}'), ( 5, 2, 4, '{"source": "OB", "periodFromMonth": 1, "periodToMonth": 12}'), ( 6, 2, 4, '{"source": "KIB", "periodFromMonth": 13, "periodToMonth": 24}'), ( 7, 2, 4, '{"source": "OB", "periodFromMonth": 13, "periodToMonth": 24}'), ( 8, 3, 5, '{"days": 7}'), ( 9, 4, 6, '{}'), (10, 4, 7, '{}'), (11, 3, 8, '{"days": 30}'), (12, 3, 9, '{}'), (13, 5, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 1, "maxOverdueDays": 7}'), (14, 5, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 8}'), (15, 5, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 1, "maxOverdueDays": 7}'), (16, 5, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 8}'), (17, 5, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 1, "maxOverdueDays": 10}'), (18, 5, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 11, "maxOverdueDays": 20}'), (19, 5, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 15}'), (20, 5, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 1, "maxOverdueDays": 10}'), (21, 5, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 11, "maxOverdueDays": 20}'), (22, 5, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 21, "maxOverdueDays": 30}'), (23, 5, 10, '{"periodFromMonth": 13, "periodToMonth": 24, "minOverdueDays": 31}'), (24, 5, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 1, "maxOverdueDays": 60}'), (25, 5, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 61, "maxOverdueDays": 90}'), (26, 5, 10, '{"periodFromMonth": 25, "periodToMonth": 36, "minOverdueDays": 91}'), (27, 5, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 1, "maxOverdueDays": 15}'), (28, 5, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 16, "maxOverdueDays": 30}'), (29, 5, 10, '{"periodFromMonth": 1, "periodToMonth": 3, "minOverdueDays": 31}'), (30, 5, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 1, "maxOverdueDays": 15}'), (31, 5, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 16, "maxOverdueDays": 30}'), (32, 5, 10, '{"periodFromMonth": 4, "periodToMonth": 6, "minOverdueDays": 31}'), (33, 5, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 21, "maxOverdueDays": 30}'), (34, 5, 10, '{"periodFromMonth": 7, "periodToMonth": 12, "minOverdueDays": 31}') ) AS m (id, group_id, metric_id, params) WHERE f.id = m.id;
ALTER TABLE stop_factors.stop_factor ALTER COLUMN group_id SET NOT NULL, ALTER COLUMN metric_id SET NOT NULL, ADD CONSTRAINT fk_stop_factor_group FOREIGN KEY (group_id) REFERENCES stop_factors.stop_factor_group (id), ADD CONSTRAINT fk_stop_factor_metric FOREIGN KEY (metric_id) REFERENCES stop_factors.stop_factor_metric (id), ADD CONSTRAINT ck_stop_factor_segment CHECK (segment IS NULL OR segment IN ('RETAIL', 'MSB')), ADD CONSTRAINT ck_stop_factor_params_is_object CHECK (jsonb_typeof(params) = 'object');
CREATE INDEX idx_stop_factor_group_id ON stop_factors.stop_factor (group_id); CREATE INDEX idx_stop_factor_metric_id ON stop_factors.stop_factor (metric_id);

ALTER TABLE stop_factors.stop_factor_condition ADD COLUMN operator VARCHAR(16), ADD COLUMN value_to TEXT;
-- Legacy conditions fire on x > value (IN for statuses); -- an UNDERWRITER threshold below the REJECTED one becomes the RANGE up to it UPDATE stop_factors.stop_factor_condition SET operator = CASE WHEN value_type IN ('ARRAY', 'STRING') THEN 'IN' ELSE 'GT' END;
UPDATE stop_factors.stop_factor_condition uw SET operator = 'RANGE', value_to = rej.value FROM stop_factors.stop_factor_condition rej WHERE uw.result = 'UNDERWRITER' AND rej.result = 'REJECTED' AND rej.stop_factor_id = uw.stop_factor_id AND uw.value_type IN ('INTEGER', 'DOUBLE') AND rej.value_type IN ('INTEGER', 'DOUBLE') AND rej.value::numeric > uw.value::numeric;
ALTER TABLE stop_factors.stop_factor_condition ALTER COLUMN operator SET NOT NULL, ALTER COLUMN result SET NOT NULL, ADD CONSTRAINT ck_stop_factor_condition_result CHECK (result IN ('REJECTED', 'UNDERWRITER')), ADD CONSTRAINT ck_stop_factor_condition_operator CHECK ( CASE WHEN value_type IN ('ARRAY', 'STRING') THEN operator = 'IN' ELSE operator IN ('GT', 'GTE', 'LT', 'LTE', 'EQ', 'RANGE', 'BETWEEN') END), ADD CONSTRAINT ck_stop_factor_condition_value_to CHECK ( CASE WHEN operator IN ('RANGE', 'BETWEEN') THEN value_to IS NOT NULL ELSE value_to IS NULL END);
-- one condition per result; SPR's table may already have such a constraint under another name CREATE UNIQUE INDEX IF NOT EXISTS ux_stop_factor_condition_result ON stop_factors.stop_factor_condition (stop_factor_id, result);

CREATE TABLE stop_factors.stop_factor_product (
    stop_factor_id BIGINT NOT NULL,
    product_id     BIGINT NOT NULL,
    CONSTRAINT pk_stop_factor_product PRIMARY KEY (stop_factor_id, product_id),
    CONSTRAINT fk_stop_factor_product_stop_factor FOREIGN KEY (stop_factor_id) REFERENCES stop_factors.stop_factor (id),
    CONSTRAINT fk_stop_factor_product_product FOREIGN KEY (product_id) REFERENCES public.product (id)
);

CREATE INDEX idx_stop_factor_product_product_id ON stop_factors.stop_factor_product (product_id);

-- A check points to the stop factor row of the group version it ran with; those rows never change
ALTER TABLE stop_factors.stop_factor_check
    ADD COLUMN product_id BIGINT,
    ADD CONSTRAINT fk_stop_factor_check_product FOREIGN KEY (product_id) REFERENCES public.product (id);

CREATE INDEX idx_stop_factor_check_stop_factor_id ON stop_factors.stop_factor_check (stop_factor_id);

rollback.sql:
DROP INDEX stop_factors.idx_stop_factor_check_stop_factor_id;
ALTER TABLE stop_factors.stop_factor_check
    DROP CONSTRAINT fk_stop_factor_check_product,
    DROP COLUMN product_id;

changeSet.sql:
-- SPR's sequences can lag behind ids inserted without them; never moves a sequence back
SELECT setval('public.stop_factor_id_generator',
              GREATEST((SELECT COALESCE(max(id), 0) FROM stop_factors.stop_factor),
                       (SELECT last_value FROM public.stop_factor_id_generator)));
SELECT setval('public.stop_factor_condition_id_generator',
              GREATEST((SELECT COALESCE(max(id), 0) FROM stop_factors.stop_factor_condition),
                       (SELECT last_value FROM public.stop_factor_condition_id_generator)));
SELECT setval('public.stop_factor_check_id_generator',
              GREATEST((SELECT COALESCE(max(id), 0) FROM stop_factors.stop_factor_check),
                       (SELECT last_value FROM public.stop_factor_check_id_generator)));
